    basicCurrent:{title:'OpenStax · Electrical current',url:'https://openstax.org/books/university-physics-volume-2/pages/9-1-electrical-current',note:'באנגלית. האיורים מדגימים מה פירוש זרימה של מטען במוליך.'},
